WITH valid AS (SELECT *, DATEDIFF(CURRENT_DATE(), started_at) / 30 months_since_started_at, UPPER(country) country_upper, COALESCE(browser, 'OTHER') browser_clean FROM sessions WHERE browser IN ('Edge', 'Firefox')) SELECT id, browser, started_at, months_since_started_at, browser_clean, SUM(months_since_started_at) OVER (ORDER BY CAST(started_at AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) months_since_started_at_sum_7d, RANK() OVER w_recent months_since_started_at_rank, AVG(months_since_started_at) OVER (ORDER BY CAST(started_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) months_since_started_at_avg_30d, CUME_DIST() OVER w_hist months_since_started_at_cume_dist, DENSE_RANK() OVER (PARTITION BY browser ORDER BY months_since_started_at NULLS LAST) months_since_started_at_dense_rank FROM valid WINDOW w_recent AS (ORDER BY months_since_started_at), w_hist AS (PARTITION BY customer_id ORDER BY months_since_started_at NULLS FIRST)
